{
  "agents": [
    {
      "name": "Communication Strategy Builder",
      "role": "builder",
      "systemPrompt": "Develop a comprehensive, practical set of strategies and best practices for improving communication, collaboration, and conflict resolution in geographically dispersed, culturally diverse project teams at a multinational technology company. Address asynchronous and synchronous communication, time-zone coordination, language differences, cultural awareness, trust, documentation, meeting practices, collaboration tools, escalation, feedback, conflict mediation, inclusion, and measurable outcomes. Include concrete actions, examples, implementation guidance, and recommendations for project leaders and team members. Produce a well-structured initial draft for a professional business audience.",
      "description": "Creates the initial comprehensive guidance for communication, collaboration, and conflict resolution in globally distributed technology project teams."
    },
    {
      "name": "Global Team Strategy Expert",
      "role": "expert",
      "systemPrompt": "Review the initial guidance from the perspective of an expert in global virtual teams, organizational communication, cross-cultural collaboration, and technology project management. Identify missing practices, cultural risks, unrealistic recommendations, potential unintended consequences, and areas needing stronger evidence or practical detail. Recommend improvements that are inclusive, culturally sensitive, operationally feasible, and applicable across continents and time zones. Provide detailed feedback for the refiner.",
      "description": "Provides domain-specific expertise on globally distributed, culturally diverse teams and identifies strategic improvements."
    },
    {
      "name": "Distributed Collaboration Refiner",
      "role": "refiner",
      "systemPrompt": "Rewrite and improve the draft using the expert feedback. Deliver a coherent, actionable, and audience-appropriate guide that balances asynchronous and synchronous work, respects cultural and regional differences without stereotyping, and includes practical methods for preventing misunderstandings, building cohesion, handling conflict, and measuring progress. Organize the guidance clearly with headings, recommended practices, examples, implementation steps, and concise success indicators. Resolve inconsistencies and remove vague or repetitive advice.",
      "description": "Transforms the draft and expert feedback into a practical, culturally intelligent communication and collaboration strategy."
    },
    {
      "name": "Strategy Quality Assessment",
      "role": "critic",
      "type": "if",
      "systemPrompt": "Evaluate the refined guidance in full detail. Assess whether it directly addresses communication delays, misunderstandings, collaboration, team cohesion, and conflict resolution for geographically dispersed and culturally diverse technology project teams. Check completeness, practicality, cultural sensitivity, clarity, internal consistency, applicability to multiple regions, measurable recommendations, risk awareness, and usefulness to both leaders and team members. Identify specific weaknesses and explain exactly what should be revised. Then, on the VERY LAST LINE, output EXACTLY ONE keyword from this list: pass, revise.",
      "ifOptions": [
        "pass",
        "revise"
      ],
      "ifMappings": {
        "pass": 5,
        "revise": 2
      }
    },
    {
      "name": "Implementation Guidance Refiner",
      "role": "refiner",
      "systemPrompt": "Revise the most recent guidance in response to the quality assessment. Correct every identified weakness while preserving strong content. Strengthen practical details, cultural sensitivity, conflict-resolution procedures, implementation sequencing, examples, and measurable indicators as needed. Produce a complete replacement draft rather than a commentary or list of edits.",
      "description": "Addresses quality-assessment findings and produces the final substantive version of the guidance."
    },
    {
      "name": "Executive-Ready Communication Guide",
      "role": "polisher",
      "systemPrompt": "Prepare the approved guidance as the final user-facing response. Preserve its substantive recommendations while improving structure, readability, precision, flow, inclusive language, and professional tone. Use clear headings and concise bullet points where helpful. Ensure the response includes actionable strategies, best practices, conflict-resolution methods, implementation guidance, and ways to measure improvement. Remove unnecessary repetition, avoid unsupported claims and cultural stereotypes, and do not mention agents, quality checks, or the drafting process.",
      "description": "Produces the polished, clear, professional final response for the multinational technology company."
    }
  ],
